    const string StoryResources="Assets/Narrative/Resources/Narrative/";
    static T StoryAsset<T>(string path) where T:ScriptableObject {var asset=AssetDatabase.LoadAssetAtPath<T>(path);if(asset==null){asset=ScriptableObject.CreateInstance<T>();AssetDatabase.CreateAsset(asset,path);}return asset;}
    static AudioClip StoryAudio(string name)=>AssetDatabase.LoadAssetAtPath<AudioClip>("Assets/Narrative/Audio/"+name+".wav");
    static StoryCondition Condition(StoryEventKind kind,string target,string value="",bool current=false)=>new StoryCondition{kind=kind,target=target,value=value,checkCurrentStateOnEnter=current};
    static NarrativeAction Action(NarrativeActionKind kind,string target="",string text="",float number=0,bool value=false,string audio=null,string completion=null)=>new NarrativeAction{kind=kind,target=target,text=text,number=number,value=value,audio=audio==null?null:StoryAudio(audio),completionId=completion};
    static NarrativeAction Circuit(string id,bool on){var path=AssetDatabase.FindAssets("t:PowerCircuit").Select(AssetDatabase.GUIDToAssetPath).First(p=>AssetDatabase.LoadAssetAtPath<PowerCircuit>(p).id==id);return new NarrativeAction{kind=NarrativeActionKind.SetCircuit,circuit=AssetDatabase.LoadAssetAtPath<PowerCircuit>(path),value=on};}
    static NarrativeBeat Beat(string id,string objective,string guidance,StoryCondition[] conditions,NarrativeAction[] enter=null,NarrativeAction[] exit=null,string message=null)=>new NarrativeBeat{id=id,title=objective,objective=objective,guidance=guidance,conditions=conditions,enter=enter??new NarrativeAction[0],exit=exit??new NarrativeAction[0],supervisorMessage=message};
    static NarrativeSequence.Cue Cue(NarrativeAction[] actions,StoryCondition wait=null,float delay=0)=>new NarrativeSequence.Cue{actions=actions,completion=wait,waitForCompletion=wait!=null,delay=delay,timeout=75};
