        var night=StoryAsset<NightDefinition>(StoryResources+"Night 1.asset");night.nightNumber=1;night.title="The New Hire";night.protagonist="Aki";night.date="2026-11-01";night.startSeconds=21*3600+50*60;night.management=data;
        night.openingLines=new[]{"Two months behind on rent.","I've lost count of how many jobs I've applied for.","Then, yesterday, someone finally called back.","An overnight security position at an old apartment building.","The pay was surprisingly good.","They didn't even ask for an interview.","I guess I can't afford to be picky."};
        night.history=new[]{
