        beats.Add(Beat("camera.off","Restart the malfunctioning camera","In the 1F utility room, switch CCTV CAMERAS off. Leave the main electrical supply alone.",new[]{Condition(StoryEventKind.CircuitChanged,"CCTV Cameras","off")},new[]{Action(NarrativeActionKind.MaintenanceStatus,"N1-CCTV","Reported"),Action(NarrativeActionKind.CctvChannel,"lift.monitor",number:3)},message:"That feed's dropped out again? The camera power switch is in the little utility room. Switch CCTV CAMERAS off, then back on. Usually clears it."));
        beats.Add(Beat("camera.on","Restore CCTV camera power","Switch CCTV CAMERAS back on, then return to the security office.",new[]{Condition(StoryEventKind.CircuitChanged,"CCTV Cameras","on")},exit:new[]{Action(NarrativeActionKind.CameraFault,"camera.fault",value:false),Action(NarrativeActionKind.MaintenanceStatus,"N1-CCTV","Resolved"),Action(NarrativeActionKind.Record,"CCTV service","Camera power restarted. Signal returned to normal.")}));
        beats.Add(Beat("keys","Borrow the stairwell key","Collect the labeled Stairwell key from the security office key board.",new[]{Condition(StoryEventKind.ItemCollected,"Stairwell",current:true)},exit:new[]{Action(NarrativeActionKind.TaskStatus,"handover","Completed")},message:"Thanks. Take the stairwell key from the board. Start with floors two through four tonight. The lift works too."));
        beats.Add(Beat("patrol2","Patrol the second floor","Visit 2F, inspect the lock on door 203, and inspect the corridor light near the middle of the hall.",new[]{Condition(StoryEventKind.AreaEntered,"floor.2"),Condition(StoryEventKind.Signal,"inspect.door.203"),Condition(StoryEventKind.Signal,"inspect.light.2")},new[]{Action(NarrativeActionKind.TaskStatus,"corridors","InProgress"),Action(NarrativeActionKind.SetTime,number:22*3600+30*60)},new[]{Action(NarrativeActionKind.Record,"2F patrol","Door 203 secured; shared corridor lighting checked.")}));
