        beats.Add(Beat("telephone","Answer the desk telephone","The desk telephone is ringing. Walk up to it and press E to answer.",new[]{Condition(StoryEventKind.SequenceCompleted,"silent-call")},new[]{Action(NarrativeActionKind.RingTelephone,"desk.telephone"),Action(NarrativeActionKind.Elevator,"lift",number:1)},new[]{Action(NarrativeActionKind.Record,"Telephone call","Caller disconnected without identifying themselves.")}));
