        for(int i=0;i<beats.Count;i++){beats[i].nextStepId=i+1<beats.Count?beats[i+1].id:"";beats[i].spawnBinding=beats[i].id.StartsWith("camera.")?"spawn.utility":beats[i].id=="patrol2"?"spawn.floor2":beats[i].id=="patrol3"?"spawn.floor3":new[]{"patrol4","maintenance.off","maintenance.on","verify4","slam"}.Contains(beats[i].id)?"spawn.floor4":beats[i].id=="arrival"?"spawn.alley":new[]{"alley.trigger","alley.voice","home","fade"}.Contains(beats[i].id)?"spawn.voice":"spawn.office";if(new[]{"arrival","alley.trigger","alley.voice","home","fade"}.Contains(beats[i].id))beats[i].scene="Alley";}night.beats=beats.ToArray();
        Document("Guard Logbook","Previous guard's shift log","23 OCT — 22:05\nEntrance checked. Parcel for Room 201 left outside as requested.\n\n24 OCT — 00:40\nFourth-floor tube slow to start. Maintenance informed. Water pressure normal.\n\n26 OCT — 01:08\nHeard someone speaking in the third-floor stairwell. No one there when I checked. Could have carried up from the entrance.\n\n28 OCT — 03:15\nLift stopped at the sixth floor twice without a call showing on the panel. Will ask the supervisor about the contacts.\n\n30 OCT — 23:50\nThe elderly resident in Room 201 asked whether I'd heard anyone outside her door after midnight. Said it sounded familiar. Didn't want to explain.\n\n02:13 AM — Another noise complaint from the fifth floor. Going upstairs to check.");
        Document("Unfinished Note","An unfinished note","Check the fifth-floor complaints against the call log.\n\nAsk the resident in 201 what she meant about the voice. She started to tell me something, then—");
